use xiom.io;

type Account = {
  owner: Str;
  balance: Float64;
  invariant: balance >= 0.0;
}

fn deposit(account: &mut Account, amount: Float64)
  requires: amount > 0.0;
  ensures: account.balance == account@pre.balance + amount;
{
  account.balance = account.balance + amount;
}

fn withdraw(account: &mut Account, amount: Float64)
  requires: amount > 0.0;
  requires: amount <= account.balance;
  ensures: account.balance == account@pre.balance - amount;
{
  account.balance = account.balance - amount;
}

fn transfer(from: &mut Account, to: &mut Account, amount: Float64)
  requires: amount > 0.0;
  requires: amount <= from.balance;
  ensures: from.balance == from@pre.balance - amount;
  ensures: to.balance == to@pre.balance + amount;
{
  withdraw(from, amount);
  deposit(to, amount);
}

fn report(account: &Account) {
  io.println(account.owner.to_str() + ": $" + account.balance.to_str());
}

fn main() -> Int {
  var alice = Account{ owner: "Alice", balance: 1000.0 };
  var bob = Account{ owner: "Bob", balance: 500.0 };

  deposit(&mut alice, 200.0);
  transfer(&mut alice, &mut bob, 300.0);

  report(&alice);
  report(&bob);

  return alice.balance as Int;
}
